          // 无需 R6 中转。旧实现 `MOV R6,rt; MUL R6,rd; MOV rd,R6` 在 rd==R6 时会先被
          // `MOV R6,rt` 覆盖掉第一操作数（如 drawstring 的 (c-32)*5），导致结果错误。
          if (inst.op === IR_OP.MUL) { this.asm(`\tMUL ${rd}, ${rt}`); }
